def P(text, style='CNBody'): return Paragraph(text, styles[style])
def H(text, level=1): return P(text, 'CNH1' if level == 1 else 'CNH2')
def code(text): return Preformatted(text, styles['CNCode'])
def bullet(text): return P('• ' + text, 'CNBody')
def footer(canvas, doc):
    canvas.saveState(); canvas.setFont('STSong-Light', 8); canvas.setFillColor(HexColor('#71808B'))
    canvas.drawString(18*mm, 12*mm, 'SC-RAG 私人项目与面试指南')
    canvas.drawRightString(192*mm, 12*mm, f'{doc.page}')
    canvas.restoreState()

def table(data, widths):
    t = Table(data, colWidths=widths, repeatRows=1)
    t.setStyle(TableStyle([
        ('FONTNAME',(0,0),(-1,-1),'STSong-Light'), ('FONTNAME',(0,0),(-1,0),'STSong-Light'),
        ('FONTSIZE',(0,0),(-1,-1),8.5), ('LEADING',(0,0),(-1,-1),13),
        ('BACKGROUND',(0,0),(-1,0),HexColor('#DCECF2')), ('TEXTCOLOR',(0,0),(-1,0),HexColor('#12304A')),
        ('GRID',(0,0),(-1,-1),0.35,HexColor('#B8C6CC')), ('VALIGN',(0,0),(-1,-1),'TOP'),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,HexColor('#F7FAFB')]), ('LEFTPADDING',(0,0),(-1,-1),6), ('RIGHTPADDING',(0,0),(-1,-1),6),
    ])); return t

story=[]
story += [P('SC-RAG', 'CNTitle'), P('面向实习求职的随机计算文献研究 Agent', 'CNSub'), P('项目实现、评测体系、系统原理与面试准备指南', 'CNSub'), Spacer(1,20), P('这份文件是个人学习与面试准备材料，不属于公开 GitHub 仓库。', 'CNQuote'), H('一页讲清项目',1), P('SC-RAG 是一个面向 stochastic computing 研究的 evidence-grounded literature agent。它把 50 篇论文转换为带页码和稳定 chunk ID 的证据，通过中英文混合检索和 alias-aware evidence planner 找到论文级证据，再让模型生成带 Claim-level citation 的回答。应用层会验证 span、chunk、论文别名和原文摘录；证据不足、比较不完整或模型输出不符合 schema 时，系统拒答。'), P('项目的差异点不在“接入了一个大模型”，而在于把研究问答拆成可测量、可审计、可失败归因的链路：检索质量、证据覆盖、生成合同、引用正确性、拒答行为和延迟都能单独评估。'), P('面试时可以用下面这段 60 秒介绍：', 'CNH2'), P('我做了一个面向随机计算论文研究的 evidence-grounded RAG agent。系统从 50 篇 PDF 建立页级索引，使用 BM25 与 multilingual dense retrieval 做 RRF 融合；对于用户明确指定的论文，系统会按 alias 单独补召回并优先规划证据。LLM 只能引用应用生成的 span ID，最终引用由服务端根据可信检索元数据解析，因此能防止模型伪造论文、页码和摘录。除了单轮问答，我还做了两遍式文献综述：先逐篇抽取方法、位流、硬件、实验和局限，再基于已验证事实做跨论文比较和可证伪研究假设。最后用 answerable/unanswerable benchmark、引用合同、拒答率、延迟和失败归因做回归。')]
story += [PageBreak(), H('一、系统架构与请求工作流'), P('系统分成离线数据管线、在线检索与回答、文献综述和评测可观测性四个层次。'), table([[P('层次','CNSmall'),P('职责','CNSmall'),P('关键代码','CNSmall')],[P('数据','CNSmall'),P('PDF → manifest → page-aware chunks；References 截断。','CNSmall'),P('src/sc_rag/ingest.py','CNSmall')],[P('检索','CNSmall'),P('BM25、中文/英文术语扩展、dense、RRF、论文别名定向搜索。','CNSmall'),P('search.py / dense.py / hybrid.py','CNSmall')],[P('生成','CNSmall'),P('结构化 JSON、Claim、span ID、repair、拒答。','CNSmall'),P('answering.py','CNSmall')],[P('研究工作流','CNSmall'),P('逐篇事实抽取 → 事实 ID 绑定 → 跨论文综合。','CNSmall'),P('literature_review.py','CNSmall')],[P('产品与评测','CNSmall'),P('FastAPI、Streamlit、回归报告、延迟与失败归因。','CNSmall'),P('api.py / ui/app.py / scripts','CNSmall')]], [35*mm,92*mm,48*mm]), H('在线问答的 10 个步骤',2), code('1. 接收 question 与 AnswerMode\n2. HybridRetriever.search(question, k=30)\n3. 提取问题中的显式论文 alias\n4. 对缺失 alias 调用 search_alias 定向补召回\n5. plan_evidence：优先每个目标论文，再填充剩余证据\n6. split_evidence_spans：生成 E1.S1 形式的 span ID\n7. LLM 只接收 untrusted source text 与可信 metadata\n8. RawAnswer Pydantic 校验；必要时只 repair 一次\n9. 应用层把 span ID 解析为真实 chunk、页码和摘录\n10. 比较不完整、证据不足或引用非法时 fail closed'), H('为什么“模型生成引用”是不可信的？',2), P('模型可以生成看起来合理的论文名、页码甚至 quote。SC-RAG 不让模型决定引用的 paper_id、page 或 excerpt，而只允许模型返回 E1.S1 这样的内部标识。应用从本次请求的证据计划中解析该标识，使用检索元数据生成最终引用。这是一个典型的“模型提议、应用裁决”边界。')]
story += [PageBreak(), H('二、离线数据管线与检索原理'), H('PDF 处理',2), P('manifest 保存 paper_id、alias、title、relative_path 和 hash；ingest 使用 PyMuPDF 逐页提取文本，保留 PDF page。chunk ID 由 paper、page、local index 和稳定 hash 组成，因此评测和引用可以复现。References/Bibliography/参考文献标题之后的内容会被截断，避免文献列表成为虚假正文证据。'), code('make manifest\nmake ingest\nmake dense-index EMBEDDING_MODEL=intfloat/multilingual-e5-small'), H('BM25 与 dense 的互补性',2), P('BM25 对术语、缩写、型号和论文别名很敏感，延迟低；dense retrieval 对语义改写和中英文表达更有优势，但可能把“看起来相似”的参考文献或背景段落排得很前。RRF 不直接比较分数，而是按各自 rank 融合：'), P('RRF(d) = Σ 1 / (k + rank_i(d))。在项目中，hybrid 的目标不是平均两个检索器，而是提升 evidence coverage，同时使用 max_per_paper 控制单篇论文占满上下文。'), H('为什么要有 alias-aware planner？',2), P('标准 top-k 可能全部来自一篇高频论文。对于“比较 [A] 和 [B]”这类问题，系统先解析显式 alias，再对每个 alias 做定向搜索并优先放入证据。这样把“目标论文是否进入证据”和“模型是否引用目标论文”拆成两个可诊断指标。')]
story += [PageBreak(), H('三、Grounded Generation 与防幻觉机制'), H('结构化输出合同',2), code('{"evidence_sufficiency":"sufficient|partial|insufficient|conflicting",\n "confidence":0.0,\n "claims":[{"text":"...","citations":[{"span_id":"E1.S1"}]}],\n "missing_information":[], "reason":"..."}'), P('RawAnswer、RawClaim 和 RawCitation 使用 extra=forbid。模型多返回字段会进入 repair；repair 后仍非法则拒答。citation 的最终 metadata 不来自模型，而来自 by_span_id。'), H('三类重要门控',2), bullet('证据不足：evidence_sufficiency=insufficient 且没有可支持 Claim 时 abstained。'), bullet('比较不完整：comparison 模式的 partial 至少要引用两个不同来源；只有一方数据时拒答。'), bullet('目标论文漏引：目标 alias 已在证据中但没有出现在 citation 时触发一次 repair；修复后仍不满足则不接受。'), H('为什么不能简单让 LLM-as-a-judge 判分？',2), P('LLM judge 自己也可能受答案措辞、引用幻觉和评测泄漏影响。SC-RAG 先用确定性合同检查 span、chunk、alias、quote 和状态，再把人工审核用于语义支持性和可替代来源。自动指标保证一致性，人工审核补足语义判断。')]
story += [PageBreak(), H('四、两遍式文献综述 Agent'), H('Pass 1：逐篇事实抽取',2), P('每篇论文独立输入有限证据，抽取 method、bitstream、hardware、evaluation、limitations 五类事实。服务端为每个事实绑定 F1、F2 等 fact_id 和真实 Citation，禁止后续综合阶段引用未验证的事实。'), H('Pass 2：跨论文综合',2), P('综合模型只接收已经绑定 fact_id 的事实表，而不是重新接收全部 PDF。ComparisonCell 必须引用 fact_ids；ResearchIdea 必须包含 observed_gap、hypothesis、proposed_experiment、falsifier 和 uncertainty。这样“研究想法”与论文事实之间保留了可审计边界。'), code('POST /literature-review\n{"topic":"低离散位流生成器的精度、硬件成本与并行化",\n "aliases":["Sobol","PSobol","P2LSG","FSM-LDSG"],\n "chunks_per_paper":5}'), H('为什么这比一次性长 Prompt 更好？',2), P('一次性把 4 篇或 50 篇论文塞进上下文，会导致 token 成本、注意力稀释、来源混淆和不可定位错误。两遍式流程把“抽取”和“综合”分开，事实 ID 作为中间表示，既节省上下文，也让失败可以定位到具体论文或具体 synthesis cell。')]
story += [PageBreak(), H('五、评测体系与真实结果解读'), H('评测分层',2), table([[P('层级','CNSmall'),P('指标','CNSmall'),P('回答的问题','CNSmall')],[P('Retrieval','CNSmall'),P('hit_any、hit_all、MRR、p95 latency','CNSmall'),P('目标论文和相关证据是否被找全？','CNSmall')],[P('Evidence planning','CNSmall'),P('explicit_target_evidence_hit_all','CNSmall'),P('目标论文是否进入实际上下文？','CNSmall')],[P('Generation','CNSmall'),P('answered/partial/abstained、repair rate','CNSmall'),P('模型是否覆盖、是否过度拒答？','CNSmall')],[P('Citation','CNSmall'),P('citation contract、gold alias recall','CNSmall'),P('引用是否来自真实证据？','CNSmall')],[P('Safety/Gating','CNSmall'),P('unanswerable abstention rate','CNSmall'),P('没有证据时是否拒答？','CNSmall')]], [35*mm,65*mm,75*mm]), H('项目中一次重要的归因',2), P('Phase 4 人工审核发现：E1 把 References 当正文，E5 在比较任务只找到一方仍返回 partial，D4 的正文实验环境被 References 切片挤出。修复分别落在三个层级：ingest 截断参考文献、comparison partial 双来源门控、索引重建。这是面试中很好的“从指标到根因再到代码修改”的闭环。'), H('如何运行完整回归',2), code('make evaluate-phase4\n# artifacts/phase4_eval.json\npython scripts/generate_phase4_human_review.py\n# artifacts/phase4_human_review.md'), P('Phase 4 报告会保存候选数、证据别名、目标 alias、模型状态、repair、延迟和失败分类，避免只报一个总分。')]
story += [PageBreak(), H('六、面试问题与专业回答'), H('Q1：为什么不用纯向量检索？',2), P('随机计算论文包含大量缩写、硬件型号、算法名和公式符号。BM25 对精确词和实体召回更稳定，dense 对语义改写更好。我们先分别评估，再用 RRF 做融合，并通过 max_per_paper 和 alias planner 保证跨论文覆盖。'), H('Q2：你的 RAG 如何防止幻觉引用？',2), P('模型只能返回 span_id；应用根据本次 evidence plan 解析 chunk、paper、page 和 excerpt。未知 span、重复引用、quote 不在证据或 schema 错误都会 fail closed。最终引用字段不是模型自由生成的。'), H('Q3：为什么 partial answer 有时也要拒答？',2), P('对开放式基础问题，partial 可以保留已支持事实并列出缺失信息；但 comparison 问题的核心任务是对照，只有一方证据时 partial 容易被误读为完成比较。因此 comparison 模式要求至少两个来源的 citation，否则拒答。门控规则应该由任务语义决定。'), H('Q4：如何证明 RAG 真的有效？',2), P('不能只展示一条漂亮回答。我们固定 50 answerable + 8 unanswerable benchmark，分别报告检索命中、显式目标证据覆盖、引用合同、可用响应率、拒答率、repair rate 和延迟；再对失败样本做 retrieval/generation/gating 归因。'), H('Q5：LLM-as-judge 的局限是什么？',2), P('它会受到答案风格、模型偏好和引用幻觉影响，且难以稳定判断 quote 是否真的来自证据。因此确定性检查负责边界合同，人工审核负责语义支持性；judge 只能作为辅助指标。'), H('Q6：如果扩展到百万篇论文，哪里会先成为瓶颈？',2), P('离线 embedding 和索引构建、在线 candidate fan-out、reranker 延迟和上下文成本会先出现问题。需要分层索引、租户/领域过滤、缓存 query embedding、限制每篇论文贡献、异步综述任务以及 trace-based cost budget。'), H('Q7：你如何定位一次失败？',2), P('先看 trace：candidate_count 是否足够、evidence_aliases 是否覆盖目标、missing_requested_aliases 是否为空；再看 generation status、repair_reason 和 citation contract。如果目标未进证据，是 retrieval/planning；进入证据但未引用，是 generation；引用字段非法，是 validation；不可回答题被回答，则是 gating。')]
story += [PageBreak(), H('七、Codespaces 演示操作手册'), H('启动前检查',2), code("cd /workspaces/SC-RAG\ngit pull origin main\nmake test\ncurl http://127.0.0.1:8000/health"), P('8501 是 Streamlit 页面端口，8000 是 FastAPI 服务端口。两个服务必须分别在两个终端以前台方式启动。不要只打开 8501；如果 8000 没有服务，页面会显示 Connection refused。'), H('标准启动方式',2), code("终端 1：\ncd /workspaces/SC-RAG\nmake api PORT=8000\n\n终端 2：\ncd /workspaces/SC-RAG\nmake setup-ui\nexport SC_RAG_API_URL=http://127.0.0.1:8000\nmake ui"), P('在 Codespaces 的 Ports 面板中打开 8501。先在终端 1 用 curl 验证 /health，再打开 UI。终端 1 不能关闭；关闭后 8501 仍可能显示页面，但所有请求都会失败。'), H('端口被占用时',2), code("curl http://127.0.0.1:8000/health\n\n# 如果 8000 已被其他服务占用\nmake api PORT=8001\n\n# 第二个终端必须使用同一个新端口\nexport SC_RAG_API_URL=http://127.0.0.1:8001\nmake ui"), H('面试演示顺序',2), bullet('打开页面后先做一个基础知识问题，展开 Claim 查看 alias、PDF 页码、span ID 和 excerpt。'), bullet('输入“比较 [Sobol] 和 [P2LSG] 的并行化方法”，展示两篇论文都进入证据。'), bullet('输入语料不支持的问题，展示 abstained、missing information 和拒答原因。'), bullet('切换 Literature Review，输入主题和至少两个 alias，展示 comparison 与 research idea。'), bullet('最后打开 artifacts/phase4_eval.json，解释一次失败如何归因到 retrieval、generation 或 gating。')]
story += [PageBreak(), H('七、简历项目描述与演示脚本'), H('简历中文版本',2), P('设计并实现面向随机计算文献研究的 evidence-grounded RAG Agent：基于 50 篇论文构建页级可引用语料，融合 BM25 与 multilingual dense retrieval，并通过 alias-aware evidence planner 保证跨论文任务的目标来源覆盖；实现结构化 Claim-level citation、span 级引用校验、模型输出 repair 和 fail-closed abstention。进一步实现两遍式文献综述 Agent，支持逐篇事实抽取、跨论文比较和带证伪条件的研究假设生成；构建 answerable/unanswerable 回归集、引用合同、延迟和失败归因评测链路，并提供 FastAPI + Streamlit 演示工作台。'), H('两分钟演示顺序',2), bullet('先问一个基础知识问题，展开一条 Claim 的 PDF 页码和摘录。'), bullet('再输入“比较 [Sobol] 和 [P2LSG]”，展示两篇论文都进入证据。'), bullet('输入一个语料没有答案的问题，展示 abstained 和缺失原因。'), bullet('打开 Literature Review，展示逐篇事实、comparison cell 和 research idea。'), bullet('最后打开 phase4_eval.json，说明你如何把失败归因到检索、生成或门控。'), H('最后检查清单',2), bullet('README 能在新 Codespace 按步骤运行，不依赖私人教程。'), bullet('公开仓库不含 raw PDFs、API key、生成报告和私有学习笔记。'), bullet('测试、评测、UI 和 API 命令都能复现。'), bullet('至少准备 E1、E5、D4 三个真实失败案例的根因和修复。'), bullet('能解释每个指标为什么存在，而不是只背结果。')]

doc = SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=16*mm, bottomMargin=18*mm, title='SC-RAG 项目与面试指南', author='SC-RAG')
